            else:
                resp=apis.phone.search_voice_messages(access_token=phone_token, query=keyword, page_index=page_index, page_limit=page_limit, sort_by='-created_at')
            if not resp:
                break
            if isinstance(resp, dict) and 'message' in resp:
                break
            all_msgs.extend(resp)
            if len(resp)<page_limit:
                break
            page_index+=1
        return all_msgs
    # contacts
    def fetch_contacts(relationship):
        contacts=[]
        page_index=0
        page_limit=20
        while True:
            resp=apis.phone.search_contacts(access_token=phone_token, relationship=relationship, page_index=page_index, page_limit=page_limit)
            if not resp or (isinstance(resp, dict) and 'message' in resp):
                break
            contacts.extend(resp)
            if len(resp)<page_limit:
                break
            page_index+=1
        return contacts
    friend_contacts=fetch_contacts('friend')
    coworker_contacts=fetch_contacts('coworker')
    friend_and_coworker_phones=set([c.get('phone_number') for c in friend_contacts if c.get('phone_number')]) | set([c.get('phone_number') for c in coworker_contacts if c.get('phone_number')])
    def extract_from_msgs(msgs, kind='text'):
        filtered=[]
        for m in msgs:
            sender_phone=m.get('sender',{}).get('phone_number')
            receiver_phone=m.get('receiver',{}).get('phone_number')
            if sender_phone in friend_and_coworker_phones and receiver_phone==our_phone:
                filtered.append(m)
        key_field='text_message_id' if kind=='text' else 'voice_message_id'
        dedup={}
        for m in filtered:
            dedup[m.get(key_field)] = m
        return list(dedup.values())
