# Extract likely promo codes: alphanum tokens length 4-20 with at least one digit,
# and mostly uppercase (or containing digits).

def extract_code_tokens(text):
    if not text:
        return []
    # grab tokens with letters/digits (exclude very short)
    tokens = re.findall(r'\b[A-Za-z0-9]{4,20}\b', text)
    out=[]
    for t in tokens:
        tt=t.strip()
        if any(ch.isdigit() for ch in tt) and any(ch.isalpha() for ch in tt):
            # normalize: uppercase, remove non-alnum
            norm=re.sub(r'[^A-Z0-9]','',tt.upper())
            if 4<=len(norm)<=20:
                out.append(norm)
        else:
            # also allow purely numeric codes length>=6? probably unlikely, but include
            if any(ch.isdigit() for ch in tt) and len(tt)>=6:
                norm=re.sub(r'[^A-Z0-9]','',tt.upper())
                out.append(norm)
    # also consider patterns after => or =
    # e.g. "=> 08E7e" or "= ABC123"
    more=[]
    for m in re.finditer(r'(?:=>|=|code\s*[:=]|coupon\s*[:=]|use\s*[:=]|SAVE\s*[:=]?)\s*([A-Za-z0-9]{4,20})', text, flags=re.I):
        norm=re.sub(r'[^A-Z0-9]','',m.group(1).upper())
        more.append(norm)
    return list(dict.fromkeys(out+more))

